/**
 * Nodo Code (modo: "Run Once for All Items")
 * Ubicacion: justo despues del nodo de Gemini, antes del Switch.
 *
 * Problema que resuelve: Gemini suele envolver el JSON en fences de markdown
 * (```json ... ```), agregar texto introductorio, o usar comillas tipograficas.
 * Este nodo normaliza y valida la salida antes de que el resto del flujo la use.
 *
 * Salida: un item con { ok, accion, confianza, datos, faltantes, mensaje_usuario }
 *         o { ok:false, error } si no se pudo parsear.
 */

const ACCIONES_VALIDAS = [
  'CREAR_TAREA',
  'CONSULTAR_TAREAS',
  'COMPLETAR_TAREA',
  'AYUDA',
  'DESCONOCIDO',
];

/** Extrae el primer objeto JSON balanceado que aparezca en el texto. */
function extraerObjetoJson(texto) {
  const inicio = texto.indexOf('{');
  if (inicio === -1) return null;

  let profundidad = 0;
  let dentroDeCadena = false;
  let escapado = false;

  for (let i = inicio; i < texto.length; i++) {
    const c = texto[i];

    if (escapado) { escapado = false; continue; }
    if (c === '\\') { escapado = true; continue; }
    if (c === '"') { dentroDeCadena = !dentroDeCadena; continue; }
    if (dentroDeCadena) continue;

    if (c === '{') profundidad++;
    else if (c === '}') {
      profundidad--;
      if (profundidad === 0) return texto.slice(inicio, i + 1);
    }
  }
  return null;
}

function limpiar(texto) {
  return String(texto)
    .replace(/```(?:json)?/gi, '')
    .replace(/[“”]/g, '"')   // comillas tipograficas dobles
    .replace(/[‘’]/g, "'")   // comillas tipograficas simples
    .replace(/,\s*([}\]])/g, '$1')     // comas colgantes
    .trim();
}

const entrada = $input.first().json;

// El campo con el texto varia segun el nodo usado; se prueban los mas comunes.
const bruto =
  entrada.text ??
  entrada.output ??
  entrada.content ??
  entrada.response ??
  entrada.message?.content ??
  entrada.candidates?.[0]?.content?.parts?.[0]?.text ??
  JSON.stringify(entrada);

let parsed = null;
let error = null;

try {
  const candidato = extraerObjetoJson(limpiar(bruto));
  if (!candidato) throw new Error('No se encontro un objeto JSON en la respuesta.');
  parsed = JSON.parse(candidato);
} catch (e) {
  error = e.message;
}

if (!parsed) {
  return [{
    json: {
      ok: false,
      accion: 'DESCONOCIDO',
      error: `Respuesta no parseable de Gemini: ${error}`,
      bruto: String(bruto).slice(0, 500),
      mensaje_usuario: 'No logre entender el mensaje. Intenta escribirlo de otra forma.',
    },
  }];
}

// Normalizacion defensiva: el resto del flujo asume estos campos siempre presentes.
const accion = ACCIONES_VALIDAS.includes(parsed.accion) ? parsed.accion : 'DESCONOCIDO';

return [{
  json: {
    ok: true,
    accion,
    confianza: typeof parsed.confianza === 'number' ? parsed.confianza : 0,
    datos: parsed.datos && typeof parsed.datos === 'object' ? parsed.datos : {},
    faltantes: Array.isArray(parsed.faltantes) ? parsed.faltantes : [],
    mensaje_usuario: parsed.mensaje_usuario ?? null,
  },
}];

/**
 * Nodo Code (modo: "Run Once for All Items")
 * Ubicacion: rama CREAR_TAREA, despues de validar que la fecha exista,
 *            justo antes del nodo Google Sheets "Append Row".
 *
 * Construye la fila exacta que espera la hoja de calculo y genera el ID.
 * El ID usa el epoch en base36 -> corto, unico y ordenable cronologicamente.
 */

const interpretacion = $input.first().json;
const d = interpretacion.datos ?? {};

// Datos del mensaje original de Telegram (ajustar el nombre del nodo si difiere).
const telegram = $('Telegram Trigger').first().json;
const usuarioId = telegram.message?.chat?.id ?? telegram.message?.from?.id ?? 'desconocido';

const ahora = $now;

/** T-<base36 del epoch>  ->  ej. "T-K3M9QZ" */
const id = 'T-' + ahora.toMillis().toString(36).toUpperCase().slice(-6);

const fila = {
  ID: id,
  Usuario: String(usuarioId),
  Materia: d.materia || 'Sin materia',
  Tarea: d.tarea || 'Sin descripcion',
  Tipo: d.tipo || 'Otro',
  Fecha: d.fecha,                       // YYYY-MM-DD, ya validado aguas arriba
  Hora: d.hora || '23:59',              // default: fin del dia
  Prioridad: d.prioridad || 'Media',
  Estado: 'Pendiente',
  FechaRegistro: ahora.toFormat('yyyy-MM-dd HH:mm'),
  RecordatorioEnviado: 'No',
};

return [{ json: fila }];

