/**
 * Nodo Code (modo: "Run Once for All Items")
 * Ubicacion: rama CONSULTAR_TAREAS, despues de leer Google Sheets.
 *
 * Aplica los filtros que devolvio Gemini y arma el mensaje de respuesta.
 * Filtra siempre por Usuario: cada estudiante solo ve sus propias tareas.
 *
 * El mensaje se arma con etiquetas HTML porque todos los nodos Telegram del
 * proyecto usan Parse Mode = HTML. Ver docs/03-diseno-workflows.md.
 */

const interpretacion = $('Sanitizar JSON').first().json;
const f = interpretacion.datos ?? {};

const telegram = $('Telegram Trigger').first().json;
const usuarioId = String(telegram.message?.chat?.id ?? '');

/** Escapa los tres caracteres que Telegram interpreta en modo HTML. */
const esc = (v) => String(v ?? '')
  .replaceAll('&', '&amp;')
  .replaceAll('<', '&lt;')
  .replaceAll('>', '&gt;');

/** Minusculas y sin acentos, para comparar lo que escribe el usuario */
const normalizar = (v) => String(v ?? '')
  .toLowerCase()
  .normalize('NFD')
  .replace(/[̀-ͯ]/g, '')
  .trim();

const orden = { Alta: 0, Media: 1, Baja: 2 };

let tareas = $input.all()
  .map(i => i.json)
  .filter(t => String(t.Usuario) === usuarioId);

if (f.solo_pendientes !== false) {
  tareas = tareas.filter(t => normalizar(t.Estado) === 'pendiente');
}
if (f.filtro_materia) {
  const m = normalizar(f.filtro_materia);
  tareas = tareas.filter(t => normalizar(t.Materia).includes(m));
}
if (f.filtro_desde) tareas = tareas.filter(t => t.Fecha >= f.filtro_desde);
if (f.filtro_hasta) tareas = tareas.filter(t => t.Fecha <= f.filtro_hasta);

// Orden: primero lo que vence antes; a igual fecha, primero lo mas prioritario.
tareas.sort((a, b) =>
  (a.Fecha ?? '').localeCompare(b.Fecha ?? '') ||
  (orden[a.Prioridad] ?? 9) - (orden[b.Prioridad] ?? 9)
);

if (tareas.length === 0) {
  return [{ json: {
    chatId: usuarioId,
    cantidad: 0,
    texto: 'No tienes tareas pendientes con esos criterios.',
  }}];
}

const lineas = tareas.map((t, i) =>
  `<b>${i + 1}. ${esc(t.Materia)}</b>  [${esc(t.Prioridad)}]\n` +
  `   ${esc(t.Tarea)}\n` +
  `   Entrega: ${esc(t.Fecha)}${t.Hora ? ' ' + esc(t.Hora) : ''}\n` +
  `   ID: <code>${esc(t.ID)}</code>`
);

return [{ json: {
  chatId: usuarioId,
  cantidad: tareas.length,
  texto: `<b>TAREAS PENDIENTES</b> (${tareas.length})\n\n${lineas.join('\n\n')}`,
}}];

/**
 * Nodo Code (modo: "Run Once for All Items")
 * Ubicacion: rama COMPLETAR_TAREA, despues de leer Google Sheets.
 *
 * Google Sheets no permite actualizar por clave: hay que localizar la fila
 * primero. Este nodo decide cual es, a partir de lo que extrajo Gemini, y
 * deja el resultado listo para un IF de dos salidas.
 *
 * Salida (siempre un unico item):
 *   estado : 'una'            -> se identifico exactamente una tarea pendiente
 *            'no_encontrada'  -> ninguna coincidencia
 *            'ya_completada'  -> la unica coincidencia ya estaba completada
 *            'varias'         -> mas de una coincidencia, hace falta el ID
 *            'sin_criterio'   -> el mensaje no aporta con que buscar
 *   ID     : identificador de la fila a actualizar (solo si estado = 'una')
 *   texto  : mensaje ya formateado para los casos que no son 'una'
 */

const interpretacion = $('Sanitizar JSON').first().json;
const d = interpretacion.datos ?? {};

const telegram = $('Telegram Trigger').first().json;
const usuarioId = String(telegram.message?.chat?.id ?? '');

/** Escapa los tres caracteres que Telegram interpreta en modo HTML. */
const esc = (v) => String(v ?? '')
  .replaceAll('&', '&amp;')
  .replaceAll('<', '&lt;')
  .replaceAll('>', '&gt;');

/** Minusculas y sin acentos, para comparar lo que escribe el usuario. */
const normalizar = (v) => String(v ?? '')
  .toLowerCase()
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .trim();

const salir = (estado, texto, ID = null) => [{
  json: { estado, texto, ID, chatId: usuarioId },
}];

// Solo se buscan tareas propias. Nunca se toca una fila de otro usuario.
const propias = $input.all()
  .map(i => i.json)
  .filter(t => String(t.Usuario) === usuarioId);

// --- 1. Por ID explicito ---------------------------------------------------
// El usuario puede escribir el ID completo ("T-UXH49X") o solo el sufijo.
if (d.id) {
  const buscado = normalizar(d.id).replace(/^t-/, '');
  const porId = propias.filter(t => normalizar(t.ID).replace(/^t-/, '') === buscado);

  if (porId.length === 0) {
    return salir('no_encontrada',
      `No encontre ninguna tarea con el identificador <code>${esc(d.id)}</code>.\n\n` +
      `Escribi <i>que tengo pendiente</i> para ver tus tareas con sus ID.`);
  }
  if (String(porId[0].Estado).toLowerCase() === 'completada') {
    return salir('ya_completada',
      `La tarea <code>${esc(porId[0].ID)}</code> ya estaba marcada como completada.`);
  }
  return salir('una', null, porId[0].ID);
}

// --- 2. Por materia y descripcion ------------------------------------------
const materia = normalizar(d.materia);
const textoTarea = normalizar(d.texto_tarea);

if (!materia && !textoTarea) {
  return salir('sin_criterio',
    'No me quedo claro cual tarea terminaste.\n\n' +
    'Deci la materia, la descripcion o el ID, por ejemplo:\n' +
    '<i>ya termine el proyecto de Bases de Datos</i>');
}

// Palabras de tres letras o menos no discriminan ("de", "el", "la").
const palabras = textoTarea.split(/\s+/).filter(p => p.length > 3);

let candidatos = propias.filter(t => {
  if (materia && !normalizar(t.Materia).includes(materia)) return false;
  if (palabras.length === 0) return true;

  const contenido = normalizar(`${t.Tarea} ${t.Tipo}`);
  return palabras.some(p => contenido.includes(p));
});

if (candidatos.length === 0) {
  return salir('no_encontrada',
    'No encontre ninguna tarea que coincida con esa descripcion.\n\n' +
    'Escribi <i>que tengo pendiente</i> para ver tus tareas.');
}

// Entre varias coincidencias, las pendientes tienen prioridad sobre las ya
// completadas: si el usuario dice "ya termine X" se refiere a una pendiente.
const pendientes = candidatos.filter(t => String(t.Estado).toLowerCase() === 'pendiente');

if (pendientes.length === 0) {
  return salir('ya_completada',
    `Esa tarea ya estaba marcada como completada: <b>${esc(candidatos[0].Materia)}</b> - ${esc(candidatos[0].Tarea)}`);
}

if (pendientes.length === 1) {
  return salir('una', null, pendientes[0].ID);
}

// Ambiguo: se listan las opciones y no se modifica nada.
const lineas = pendientes.map((t, i) =>
  `<b>${i + 1}. ${esc(t.Materia)}</b>\n` +
  `   ${esc(t.Tarea)}\n` +
  `   ID: <code>${esc(t.ID)}</code>`
);

return salir('varias',
  `Encontre ${pendientes.length} tareas que coinciden. Deci cual con su ID:\n\n` +
  lineas.join('\n\n'));;
